head.script:
scwin.init = function() {
    var jsonData = [{
            "col1": "sample1",
            "col2": "1"
        },
        {
            "col1": "sample1",
            "col2": "1"
        },
        {
            "col1": "sample1",
            "col2": "2"
        },
        {
            "col1": "sample2",
            "col2": "2"
        },
        {
            "col1": "sample2",
            "col2": "2"
        },
        {
            "col1": "sample2",
            "col2": "1"
        },
        {
            "col1": "sample2",
            "col2": "1"
        }
    ];
    dataList1.setJSON(jsonData);
}
scwin.gridView1_onafteredit = function(row, col, value) {
    log = "afterEdit";
    //alert('afterEdit');
};
scwin.trigger1_onclick = function(e) {
    dataList1.insertRow();
};
scwin.gridView1_oncellclick = function(row, col) {
    console.log('click');
};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.checkError = function() {
    var log = WebSquare.logger.getErrorLog();
    return log.indexOf("cannot set property 'innerHTML' of undefined") == -1;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();

    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridBodyDefault_rowNumber')[5].innerText == '8'", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_5_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView1_cell_5_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1___selectbox_col2_itemTable_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log", "afterEdit");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "log = ''");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_5_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView1_cell_5_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1___selectbox_col2_itemTable_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log == 'afterEdit'", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.checkError()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    window.log = "";
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 04-Apr-2018
}
